<script setup lang="ts">
const {data:posts}=await usePreviewFetch<any[]>('/api/posts',{query:{type:'reference',limit:100},default:()=>[]})
const search=ref(''),category=ref('')
const categories=computed(()=>[...new Set(posts.value.map(p=>String(p.meta?.category||'Основы')))])
const filtered=computed(()=>posts.value.filter(p=>(!category.value||(p.meta?.category||'Основы')===category.value)&&`${p.title} ${p.excerpt}`.toLowerCase().includes(search.value.toLowerCase())))
useSiteSeo({title:'Справочник D&D — правила, вопросы и советы новичкам',description:'Материалы о персонажах, проверках, заклинаниях и правилах Dungeons & Dragons. Редакции 2014 и 2024 обозначены отдельно.'})
</script>
<template><section class="section"><div class="container-x"><SectionTitle icon="book" as="h1">Справочник D&D</SectionTitle><p class="mb-6 max-w-3xl text-ash">Ответы на игровые вопросы. Всегда уточняйте редакцию правил и договорённости вашего стола.</p><div class="mb-8 grid gap-4 sm:grid-cols-2"><div><label for="reference-search" class="mb-1 block text-sm">Найти материал</label><input id="reference-search" v-model="search" class="input" type="search"/></div><div><label for="reference-category" class="mb-1 block text-sm">Категория</label><select id="reference-category" v-model="category" class="input"><option value="">Все категории</option><option v-for="c in categories" :key="c">{{c}}</option></select></div></div><p v-if="!posts.length" class="card text-ash">Материалы справочника готовятся к публикации.</p><p v-else-if="!filtered.length" class="text-ash">По вашему запросу ничего не найдено.</p><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><NuxtLink v-for="post in filtered" :key="post.id" :to="`/spravochnik/${post.slug}`" class="card"><img v-if="post.cover" :src="post.cover" :alt="post.meta?.coverAlt||post.title" class="mb-4 aspect-video w-full rounded-xl object-cover" loading="lazy"/><p class="text-xs text-ash">{{post.meta?.category||'Основы'}} · {{post.meta?.edition||'Редакция указана в материале'}}</p><h2 class="mt-2 text-2xl">{{post.title}}</h2><p class="mt-3 text-ash">{{post.excerpt}}</p></NuxtLink></div></div></section></template>
